payload.text:
{"check_build": {"code": "script({
  title: "Outpost 928: Endor Canopy Starbase",
  description: "Classic 1970s Space Base reimagined in the Ewok village canopy of Endor.",
  palette: {
    bark: { mix: ["reddish brown", "dark brown", "dark orange"] },
    wood: "reddish brown",
    darkWood: "dark brown",
    timber: "dark orange",
    plank: "tan",
    spaceGrey: "light bluish grey",
    darkGrey: "dark bluish grey",
    spaceBlue: "blue",
    transYellow: "trans-yellow",
    transRed: "trans-red",
    transGreen: "trans-green",
    foliage: { mix: ["dark green", "green", "olive green"] },
    moss: "green",
    rock: { mix: ["light bluish grey", "dark bluish grey"] },
    gold: "pearl gold"
  }
});

// --------------------------------------------------------------------------
// 1. FOREST FLOOR & ROCKY CRATER TERRAIN
// --------------------------------------------------------------------------
section("Forest_Terrain", [
  // Irregular mossy ground mounds around tree bases
  floor({ at: [-28, 0, -8], size: [22, 22], colour: "moss", layers: 1 }),
  floor({ at: [8, 0, -12], size: [22, 20], colour: "moss", layers: 1 }),
  // Connecting forest trail / lunar-style weathered clearing
  floor({ at: [-10, 1, -6], size: [22, 14], colour: "dark tan", layers: 1, top: "tile" }),

  // Stepped mossy contour mounds around left tree
  floor({ at: [-26, 1, -6], size: [18, 18], colour: "dark green", layers: 1 }),
  floor({ at: [-24, 2, -4], size: [14, 14], colour: "bark", layers: 1 }),

  // Stepped mossy contour mounds around right tree
  floor({ at: [10, 1, -10], size: [18, 16], colour: "dark green", layers: 1 }),
  floor({ at: [12, 2, -8], size: [14, 12], colour: "bark", layers: 1 }),

  // Weathered Endor boulders / Classic Space grey crater rocks
  box({ at: [-6, 2, -5], size: [4, 6, 3], colour: "rock", interior: "solid" }),
  place({ part: "3039", at: [-6, 8, -5], colour: "light bluish grey", turn: 0 }),
  place({ part: "3039", at: [-4, 8, -5], colour: "dark bluish grey", turn: 0 }),

  box({ at: [3, 2, 4], size: [3, 5, 4], colour: "rock", interior: "solid" }),
  place({ part: "3039", at: [3, 7, 4], colour: "light bluish grey", turn: 90 }),

  // Classic Space crater sensor beacon on rocks
  place({ part: "3062b", at: [-5, 8, -3], colour: "light bluish grey" }),
  place({ part: "4740", at: [-5, 11, -3], colour: "trans-yellow" }),
  place({ part: "3957a", at: [-5, 12, -3], colour: "light bluish grey" })
]);

// --------------------------------------------------------------------------
// 2. TREE TRUNKS WITH INDUSTRIAL RETRO-SPACE CONDUITS
// --------------------------------------------------------------------------
section("Tree_Trunks", [
  // LEFT REDWOOD TRUNK (Massive ancient tree, base at y=3 up to canopy at y=75)
  // Log-textured core massing
  box({ at: [-22, 3, -2], size: [10, 72, 10], colour: "bark", texture: "log", interior: "solid" }),

  // Flared root buttresses in 4 diagonal directions
  // North-West root buttress
  box({ at: [-24, 3, -4], size: [3, 9, 3], colour: "darkWood", interior: "solid" }),
  place({ part: "3039", at: [-24, 12, -4], colour: "darkWood", turn: 0 }),
  // North-East root buttress
  box({ at: [-13, 3, -4], size: [3, 9, 3], colour: "darkWood", interior: "solid" }),
  place({ part: "3039", at: [-13, 12, -4], colour: "darkWood", turn: 0 }),
  // South-West root buttress
  box({ at: [-24, 3, 7], size: [3, 9, 3], colour: "darkWood", interior: "solid" }),
  place({ part: "3039", at: [-24, 12, 8], colour: "darkWood", turn: 180 }),
  // South-East root buttress
  box({ at: [-13, 3, 7], size: [3, 9, 3], colour: "darkWood", interior: "solid" }),
  place({ part: "3039", at: [-13, 12, 8], colour: "darkWood", turn: 180 }),

  // Embedded Ground Airlock at Left Tree Base (facing Front -Z)
  box({ at: [-19, 3, -3], size: [4, 15, 2], colour: "spaceBlue", interior: "solid" }),
  place({ part: "60596", at: [-19, 3, -3], colour: "spaceBlue", turn: 0 }),
  place({ part: "60616a", at: [-19, 3, -3], colour: "spaceGrey", turn: 0 }),
  place({ part: "4081b", at: [-20, 15, -3], colour: "spaceGrey", turn: 0 }),
  place({ part: "6141", at: [-20, 17, -3], colour: "trans-yellow" }),

  // Retro Classic Space vertical conduit & climbing ladder on Left Trunk
  ...range(24).map(i => place({ part: "3062b", at: [-12, 3 + i * 3, 3], colour: "spaceGrey" })),
  ...range(8).map(i => place({ part: "4081b", at: [-12, 3 + i * 9, 2], colour: "darkGrey", turn: 90 })),
  ...range(8).map(i => place({ part: "6141", at: [-12, 5 + i * 9, 2], colour: "trans-yellow" })),

  // RIGHT REDWOOD TRUNK (Base at y=3 up to flight deck at y=66)
  box({ at: [14, 3, -6], size: [8, 63, 8], colour: "bark", texture: "log", interior: "solid" }),

  // Flared root buttresses around right tree
  box({ at: [12, 3, -8], size: [3, 9, 3], colour: "darkWood", interior: "solid" }),
  place({ part: "3039", at: [12, 12, -8], colour: "darkWood", turn: 0 }),
  box({ at: [21, 3, -8], size: [3, 9, 3], colour: "darkWood", interior: "solid" }),
  place({ part: "3039", at: [21, 12, -8], colour: "darkWood", turn: 0 }),
  box({ at: [12, 3, 1], size: [3, 9, 3], colour: "darkWood", interior: "solid" }),
  place({ part: "3039", at: [12, 12, 2], colour: "darkWood", turn: 180 }),
  box({ at: [21, 3, 1], size: [3, 9, 3], colour: "darkWood", interior: "solid" }),
  place({ part: "3039", at: [21, 12, 2], colour: "darkWood", turn: 180 }),

  // Power umbilical & trans-yellow sensory crystals climbing Right Trunk
  ...range(21).map(i => place({ part: "3062b", at: [13, 3 + i * 3, -3], colour: "spaceGrey" })),
  ...range(7).map(i => place({ part: "3062b", at: [13, 3 + i * 9, -4], colour: "trans-yellow" }))
]);

// --------------------------------------------------------------------------
// 3. FLIGHT DECK / LANDING PLATFORM (Right Tree, y = 66)
// --------------------------------------------------------------------------
section("Landing_Platform", [
  // Radial heavy timber brackets supporting deck from trunk
  ...range(4).map(i => place({ part: "3660b", at: [12 + (i % 2) * 8, 63, -7 + Math.floor(i / 2) * 8], colour: "darkWood", turn: (i * 90) % 360 })),

  // Main Deck Structural Slabs
  floor({ at: [7, 66, -11], size: [22, 18], colour: "wood", layers: 2 }),

  // Deck Tiled Surface Finish: Classic Space Runway + Ewok Timber Planks
  // Perimeter timber border
  floor({ at: [7, 68, -11], size: [22, 18], colour: "timber", layers: 1, top: "tile" }),
  // Central Classic Space Blue Landing Pad Zone
  floor({ at: [11, 69, -7], size: [14, 10], colour: "spaceBlue", layers: 1, top: "tile" }),
  // Landing Arrow / Chevron in Classic Space Grey & Yellow
  floor({ at: [15, 70, -6], size: [6, 2], colour: "spaceGrey", layers: 1, top: "tile" }),
  floor({ at: [17, 70, -4], size: [2, 4], colour: "spaceGrey", layers: 1, top: "tile" }),
  floor({ at: [16, 70, -2], size: [4, 2], colour: "transYellow", layers: 1, top: "tile" }),

  // Runway threshold lights (alternating trans-yellow, trans-red, trans-green)
  place({ part: "6141", at: [11, 70, -7], colour: "trans-green" }),
  place({ part: "6141", at: [11, 70, 2], colour: "trans-green" }),
  place({ part: "6141", at: [24, 70, -7], colour: "trans-red" }),
  place({ part: "6141", at: [24, 70, 2], colour: "trans-red" }),
  ...range(4).map(i => place({ part: "6141", at: [13 + i * 3, 70, -8], colour: "trans-yellow" })),
  ...range(4).map(i => place({ part: "6141", at: [13 + i * 3, 70, 3], colour: "trans-yellow" })),

  // Perimeter rustic wooden lattice railings with Classic Space perimeter floodlights
  // Front railing
  place({ part: "3633", at: [8, 69, -11], colour: "wood", turn: 0 }),
  place({ part: "3633", at: [12, 69, -11], colour: "wood", turn: 0 }),
  place({ part: "3633", at: [20, 69, -11], colour: "wood", turn: 0 }),
  place({ part: "3633", at: [24, 69, -11], colour: "wood", turn: 0 }),
  // Back railing
  place({ part: "3633", at: [8, 69, 6], colour: "wood", turn: 180 }),
  place({ part: "3633", at: [12, 69, 6], colour: "wood", turn: 180 }),
  place({ part: "3633", at: [20, 69, 6], colour: "wood", turn: 180 }),
  place({ part: "3633", at: [24, 69, 6], colour: "wood", turn: 180 }),
  // Right railing
  place({ part: "3633", at: [28, 69, -10], colour: "wood", turn: 90 }),
  place({ part: "3633", at: [28, 69, -6], colour: "wood", turn: 90 }),
  place({ part: "3633", at: [28, 69, -2], colour: "wood", turn: 90 }),
  place({ part: "3633", at: [28, 69, 2], colour: "wood", turn: 90 }),

  // Corner floodlight posts (Classic Space tap piece + trans-yellow beacon)
  place({ part: "3004", at: [7, 69, -11], colour: "spaceGrey" }),
  place({ part: "4599b", at: [7, 72, -11], colour: "spaceGrey", turn: 0 }),
  place({ part: "6141", at: [7, 75, -11], colour: "trans-yellow" }),

  place({ part: "3004", at: [28, 69, -11], colour: "spaceGrey" }),
  place({ part: "4599b", at: [28, 72, -11], colour: "spaceGrey", turn: 0 }),
  place({ part: "6141", at: [28, 75, -11], colour: "trans-yellow" }),

  place({ part: "3004", at: [28, 69, 6], colour: "spaceGrey" }),
  place({ part: "4599b", at: [28, 72, 6], colour: "spaceGrey", turn: 180 }),
  place({ part: "6141", at: [28, 75, 6], colour: "trans-yellow" }),

  // Communications Tower / Radar Array (Corner of Flight Deck)
  box({ at: [25, 69, -9], size: [3, 6, 3], colour: "darkWood", interior: "solid" }),
  place({ part: "3941", at: [25, 75, -9], colour: "spaceGrey" }),
  place({ part: "3941", at: [25, 78, -9], colour: "spaceGrey" }),
  place({ part: "3943b", at: [24, 81, -10], colour: "spaceGrey" }),
  place({ part: "3960", at: [24, 87, -10], colour: "trans-yellow" }),
  place({ part: "4589", at: [25, 89, -9], colour: "spaceBlue" }),
  place({ part: "3957a", at: [25, 92, -9], colour: "spaceGrey" })
]);

// --------------------------------------------------------------------------
// 4. VILLAGE COMMAND POD & TRANS-YELLOW OBSERVATION DOME (Left Tree, y = 75)
// --------------------------------------------------------------------------
section("Command_Pod", [
  // Radial support brackets beneath Command Pod
  ...range(4).map(i => place({ part: "3660b", at: [-24 + (i % 2) * 12, 72, -4 + Math.floor(i / 2) * 12], colour: "darkWood", turn: (i * 90) % 360 })),

  // Wooden Platform Deck
  floor({ at: [-26, 75, -6], size: [18, 18], colour: "wood", layers: 2 }),
  floor({ at: [-26, 77, -6], size: [18, 18], colour: "timber", layers: 1, top: "tile" }),

  // Circular / Octagonal Log Command Cabin
  box({ at: [-24, 78, -4], size: [14, 15, 14], colour: "timber", texture: "log", interior: "empty" }),

  // Forward viewing window (Classic Space Trans-Yellow Pane in Timber Frame)
  place({ part: "60594", at: [-21, 81, -4], colour: "spaceBlue", turn: 0 }),
  place({ part: "60603", at: [-21, 81, -4], colour: "trans-yellow", turn: 0 }),

  // Side observation windows
  place({ part: "60593", at: [-24, 81, 1], colour: "spaceBlue", turn: 90 }),
  place({ part: "60602", at: [-24, 81, 1], colour: "trans-yellow", turn: 90 }),

  place({ part: "60593", at: [-11, 81, 1], colour: "spaceBlue", turn: 270 }),
  place({ part: "60602", at: [-11, 81, 1], colour: "trans-yellow", turn: 270 }),

  // Door opening onto the walkway / bridge
  place({ part: "60596", at: [-13, 78, 3], colour: "spaceBlue", turn: 270 }),
  place({ part: "60616a", at: [-13, 78, 3], colour: "wood", turn: 270 }),

  // STEPPED TRANS-YELLOW GEODESIC OBSERVATION DOME (The Starbase Roof)
  // Ring 1 (base ring at y = 93)
  ...range(6).map(i => place({ part: "3039", at: [-23 + i * 2, 93, -5], colour: "trans-yellow", turn: 0 })),
  ...range(6).map(i => place({ part: "3039", at: [-23 + i * 2, 93, 9], colour: "trans-yellow", turn: 180 })),
  ...range(6).map(i => place({ part: "3039", at: [-25, 93, -3 + i * 2], colour: "trans-yellow", turn: 90 })),
  ...range(6).map(i => place({ part: "3039", at: [-11, 93, -3 + i * 2], colour: "trans-yellow", turn: 270 })),

  // Ring 2 (upper stepped ring at y = 96)
  floor({ at: [-22, 96, -2], size: [10, 10], colour: "spaceBlue", layers: 1 }),
  ...range(4).map(i => place({ part: "3039", at: [-21 + i * 2, 97, -3], colour: "trans-yellow", turn: 0 })),
  ...range(4).map(i => place({ part: "3039", at: [-21 + i * 2, 97, 7], colour: "trans-yellow", turn: 180 })),
  ...range(4).map(i => place({ part: "3039", at: [-23, 97, -1 + i * 2], colour: "trans-yellow", turn: 90 })),
  ...range(4).map(i => place({ part: "3039", at: [-13, 97, -1 + i * 2], colour: "trans-yellow", turn: 270 })),

  // Dome Zenith Cap (y = 100)
  place({ part: "3960", at: [-19, 100, 1], colour: "trans-yellow" }),
  place({ part: "4589", at: [-18, 102, 2], colour: "pearl gold" }),
  place({ part: "3957a", at: [-18, 105, 2], colour: "spaceGrey" }),

  // Balcony Log Railing & Ewok Communications Drums
  place({ part: "3633", at: [-25, 78, -6], colour: "wood", turn: 0 }),
  place({ part: "3633", at: [-21, 78, -6], colour: "wood", turn: 0 }),
  place({ part: "3633", at: [-17, 78, -6], colour: "wood", turn: 0 }),
  place({ part: "3633", at: [-13, 78, -6], colour: "wood", turn: 0 }),

  // Ewok War Drums wired with Classic Space microphones
  place({ part: "3062b", at: [-25, 78, -5], colour: "darkWood" }),
  place({ part: "4032b", at: [-25, 81, -5], colour: "tan" }),
  place({ part: "4599b", at: [-25, 82, -5], colour: "spaceGrey", turn: 0 }),

  place({ part: "3062b", at: [-13, 78, -5], colour: "darkWood" }),
  place({ part: "4032b", at: [-13, 81, -5], colour: "tan" }),
  place({ part: "4599b", at: [-13, 82, -5], colour: "spaceGrey", turn: 0 })
]);

// --------------------------------------------------------------------------
// 5. THE SUSPENSION SKYBRIDGE (Spanning Left & Right Canopy)
// --------------------------------------------------------------------------
section("Suspension_Bridge", [
  // Catenary stepped walkway from x = -10 (y = 77) to x = 7 (y = 68)
  // Segment 1 (at Left Command Pod exit, y = 76)
  floor({ at: [-10, 76, 2], size: [4, 4], colour: "wood", layers: 1, top: "tile" }),
  place({ part: "3633", at: [-10, 77, 2], colour: "darkWood", turn: 0 }),
  place({ part: "3633", at: [-10, 77, 5], colour: "darkWood", turn: 180 }),
  place({ part: "6141", at: [-10, 77, 2], colour: "trans-yellow" }),
  place({ part: "6141", at: [-7, 77, 2], colour: "trans-yellow" }),

  // Segment 2 (slight dip, y = 73)
  floor({ at: [-6, 73, 1], size: [4, 4], colour: "wood", layers: 1, top: "tile" }),
  place({ part: "3633", at: [-6, 74, 1], colour: "darkWood", turn: 0 }),
  place({ part: "3633", at: [-6, 74, 4], colour: "darkWood", turn: 180 }),
  place({ part: "6141", at: [-6, 74, 1], colour: "trans-red" }),
  place({ part: "6141", at: [-3, 74, 1], colour: "trans-yellow" }),

  // Segment 3 (lowest mid-span dip, y = 70)
  floor({ at: [-2, 70, 0], size: [5, 4], colour: "wood", layers: 1, top: "tile" }),
  place({ part: "3633", at: [-2, 71, 0], colour: "darkWood", turn: 0 }),
  place({ part: "3633", at: [-2, 71, 3], colour: "darkWood", turn: 180 }),
  place({ part: "6141", at: [-2, 71, 0], colour: "trans-yellow" }),
  place({ part: "6141", at: [2, 71, 0], colour: "trans-red" }),

  // Segment 4 (connecting to Flight Deck, y = 68)
  floor({ at: [3, 68, -1], size: [4, 4], colour: "wood", layers: 1, top: "tile" }),
  place({ part: "3633", at: [3, 69, -1], colour: "darkWood", turn: 0 }),
  place({ part: "3633", at: [3, 69, 2], colour: "darkWood", turn: 180 }),
  place({ part: "6141", at: [3, 69, -1], colour: "trans-yellow" }),
  place({ part: "6141", at: [6, 69, -1], colour: "trans-yellow" })
]);

// --------------------------------------------------------------------------
// 6. STAR-GLIDER "LL-E9" (Parked on Flight Deck)
// --------------------------------------------------------------------------
section("Star_Glider", [
  // Spacecraft centered at [18, 71, -3] on the landing pad
  // Rustic wooden landing skids
  place({ part: "3020", at: [14, 71, -5], colour: "wood" }),
  place({ part: "3020", at: [20, 71, -5], colour: "wood" }),
  place({ part: "3020", at: [14, 71, 1], colour: "wood" }),
  place({ part: "3020", at: [20, 71, 1], colour: "wood" }),

  // Fuselage Lower Hull (Classic Space Blue & Light Bluish Grey)
  box({ at: [16, 72, -6], size: [4, 3, 10], colour: "spaceBlue", interior: "solid" }),

  // Swept Delta Wings (Classic Space Blue wedge plates & slopes)
  // Left Wing (toward -X)
  place({ part: "41770a", at: [12, 72, -4], colour: "spaceBlue", turn: 0 }),
  place({ part: "41770a", at: [12, 72, 0], colour: "spaceBlue", turn: 0 }),
  place({ part: "3020", at: [10, 72, -2], colour: "spaceGrey" }),
  place({ part: "6141", at: [10, 73, -2], colour: "trans-red" }), // Port navigation light

  // Right Wing (toward +X)
  place({ part: "41769a", at: [20, 72, -4], colour: "spaceBlue", turn: 0 }),
  place({ part: "41769a", at: [20, 72, 0], colour: "spaceBlue", turn: 0 }),
  place({ part: "3020", at: [22, 72, -2], colour: "spaceGrey" }),
  place({ part: "6141", at: [22, 73, -2], colour: "trans-green" }), // Starboard navigation light

  // Sloped Aero Nose (Arrowhead Profile)
  place({ part: "3039", at: [16, 75, -6], colour: "spaceBlue", turn: 0 }),
  place({ part: "3039", at: [18, 75, -6], colour: "spaceBlue", turn: 0 }),
  // Classic Space Logo motif on the nose
  place({ part: "3069b", at: [17, 75, -7], colour: "pearl gold" }),
  place({ part: "54200", at: [18, 75, -7], colour: "red", turn: 0 }),

  // Cockpit: Trans-Yellow Windscreen & Pilot Station
  place({ part: "4079", at: [17, 75, -3], colour: "spaceGrey", turn: 0 }),
  place({ part: "3829c01", at: [17, 75, -4], colour: "spaceBlue", turn: 0 }),
  place({ part: "3823", at: [16, 75, -5], colour: "trans-yellow", turn: 0 }),

  // Twin Rocket Thrusters with Trans-Yellow Exhaust Plumes
  // Left Booster
  place({ part: "3941", at: [15, 74, 4], colour: "spaceGrey" }),
  place({ part: "3942c", at: [15, 77, 4], colour: "spaceGrey", turn: 180 }),
  place({ part: "3943b", at: [14, 74, 6], colour: "trans-yellow", turn: 180 }),
  // Right Booster
  place({ part: "3941", at: [19, 74, 4], colour: "spaceGrey" }),
  place({ part: "3942c", at: [19, 77, 4], colour: "spaceGrey", turn: 180 }),
  place({ part: "3943b", at: [18, 74, 6], colour: "trans-yellow", turn: 180 }),

  // Ewok Hang-Glider Lashings / Wooden Stabilizer Fin
  place({ part: "3010", at: [17, 75, 2], colour: "timber" }),
  place({ part: "3040b", at: [17, 78, 2], colour: "spaceBlue", turn: 180 }),
  place({ part: "3957a", at: [17, 81, 2], colour: "spaceGrey" })
]);

// --------------------------------------------------------------------------
// 7. KINETIC SATELLITE LAUNCHER (Canopy Catapult) & FOREST FOLIAGE
// --------------------------------------------------------------------------
section("Canopy_Details", [
  // Cantilever timber boom extending forward from Left Tree at y = 84
  box({ at: [-20, 84, -9], size: [4, 3, 6], colour: "darkWood", interior: "solid" }),

  // Catapult A-frame pivot posts
  place({ part: "3010", at: [-20, 87, -8], colour: "wood" }),
  place({ part: "3010", at: [-17, 87, -8], colour: "wood" }),

  // Catapult Launch Arm (angled throwing spar)
  place({ part: "3008", at: [-19, 90, -11], colour: "wood", turn: 0 }),
  // Heavy rocky counterweight box
  box({ at: [-19, 87, -6], size: [2, 6, 2], colour: "spaceGrey", interior: "solid" }),

  // Payload: Classic Space Orbital Sensor Satellite Probe
  place({ part: "4740", at: [-19, 93, -11], colour: "trans-yellow" }),
  place({ part: "4589", at: [-19, 94, -11], colour: "trans-yellow" }),
  place({ part: "3957a", at: [-19, 97, -11], colour: "spaceGrey" }),

  // Lush Endor Redwood Canopy Branches & Foliage
  // High branching boughs from Left Tree
  place({ part: "2417", at: [-28, 95, -7], colour: "dark green", turn: 0 }),
  place({ part: "2417", at: [-14, 98, -8], colour: "green", turn: 90 }),
  place({ part: "2417", at: [-29, 96, 5], colour: "green", turn: 180 }),
  place({ part: "2417", at: [-13, 97, 6], colour: "dark green", turn: 270 }),
  place({ part: "2423", at: [-22, 102, -8], colour: "lime", turn: 0 }),
  place({ part: "2423", at: [-16, 104, 7], colour: "green", turn: 180 }),

  // High branching boughs from Right Tree
  place({ part: "2417", at: [6, 88, -10], colour: "dark green", turn: 0 }),
  place({ part: "2417", at: [23, 90, -10], colour: "green", turn: 90 }),
  place({ part: "2417", at: [6, 89, 4], colour: "green", turn: 180 }),
  place({ part: "2417", at: [24, 91, 3], colour: "dark green", turn: 270 }),
  place({ part: "2423", at: [14, 94, -11], colour: "lime", turn: 0 }),
  place({ part: "2423", at: [18, 95, 6], colour: "green", turn: 180 })
]);

// --------------------------------------------------------------------------
// 8. FOREST FLOOR ROVER & EXPEDITION CAMP
// --------------------------------------------------------------------------
section("Ground_Rover_and_Camp", [
  // Classic Space 4-Wheel Forest Buggy on the clearing trail at [x = 0, y = 2, z = 0]
  // Wheel holders and balloon tires
  place({ part: "4600", at: [-3, 2, -3], colour: "spaceGrey", wheels: "black" }),
  place({ part: "4600", at: [1, 2, -3], colour: "spaceGrey", wheels: "black" }),
  place({ part: "4600", at: [-3, 2, 2], colour: "spaceGrey", wheels: "black" }),
  place({ part: "4600", at: [1, 2, 2], colour: "spaceGrey", wheels: "black" }),

  // Rover Chassis (Classic Space Blue & Grey)
